<?php
/** V2 order confirmation. @package SkyyRoseFlagship2
 * @var WC_Order|false $order
 */
defined( 'ABSPATH' ) || exit;
?>
<section class="sr2-thankyou sr2-c-service" data-sr2-route="checkout"><?php if ( $order ) : do_action( 'woocommerce_before_thankyou', $order->get_id() ); ?><?php if ( $order->has_status( 'failed' ) ) : ?><p class="sr2-c-status" data-state="error"><span><?php esc_html_e( 'Payment', 'skyyrose-flagship-2' ); ?></span><?php esc_html_e( 'Payment did not complete. Nothing was charged.', 'skyyrose-flagship-2' ); ?></p><p><a class="sr2-c-action" href="<?php echo esc_url( $order->get_checkout_payment_url() ); ?>"><?php esc_html_e( 'Try payment again', 'skyyrose-flagship-2' ); ?></a></p><?php else : ?><p class="sr2-c-kicker"><?php esc_html_e( 'Order received', 'skyyrose-flagship-2' ); ?></p><h1><?php esc_html_e( 'Thank you.', 'skyyrose-flagship-2' ); ?></h1><p><?php esc_html_e( 'Your confirmation and the next order update will go to the email on your order.', 'skyyrose-flagship-2' ); ?></p><dl class="sr2-thankyou__details"><div><dt><?php esc_html_e( 'Order', 'skyyrose-flagship-2' ); ?></dt><dd><?php echo esc_html( $order->get_order_number() ); ?></dd></div><div><dt><?php esc_html_e( 'Date', 'skyyrose-flagship-2' ); ?></dt><dd><?php echo esc_html( wc_format_datetime( $order->get_date_created() ) ); ?></dd></div><div><dt><?php esc_html_e( 'Total', 'skyyrose-flagship-2' ); ?></dt><dd><?php echo wp_kses_post( $order->get_formatted_order_total() ); ?></dd></div></dl><?php wc_get_template( 'order/order-details.php', array( 'order_id' => $order->get_id(), 'show_downloads' => $order->has_downloadable_item() && $order->is_download_permitted() ) ); do_action( 'woocommerce_thankyou_' . $order->get_payment_method(), $order->get_id() ); do_action( 'woocommerce_thankyou', $order->get_id() ); ?><?php endif; ?><?php else : ?><p class="sr2-c-kicker"><?php esc_html_e( 'Order received', 'skyyrose-flagship-2' ); ?></p><h1><?php esc_html_e( 'Thank you.', 'skyyrose-flagship-2' ); ?></h1><?php endif; ?></section>
